package io.ecosync.database;

import io.ecosync.credentials.DatabaseCredentials;
import io.ecosync.organizations.TenantDirectory;
import java.time.Instant;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;

/** Durable control plane. No source JDBC access; authorization is repeated by the data plane. */
@Service @ConditionalOnProperty(name="ecosync.database.enabled",havingValue="true")
public class DatabaseRegistry {
 public record Registration(String displayName,String databaseType,String host,int port,String databaseName,List<String> schemas,boolean tls,String username,String password){@Override public String toString(){return "DatabaseRegistration[credentials=REDACTED]";}}
 public record Scope(String role,List<String> columns,boolean approved){}
 private record Revision(UUID org,UUID id,long version,String type,String host,int port,String database,List<String> schemas,boolean tls,UUID credential,String fingerprint,String state,String health){}
 private final JdbcTemplate db;private final TenantDirectory tenants;private final DatabaseCredentials secrets;private final DatabasePolicy policy;private final DatabaseAssertions assertions;private final DatabaseGateway gateway;private final JsonMapper json;private final TransactionTemplate tx;private final Object[] locks=new Object[64];
 public DatabaseRegistry(JdbcTemplate db,TenantDirectory tenants,DatabaseCredentials secrets,DatabasePolicy policy,DatabaseAssertions assertions,DatabaseGateway gateway,JsonMapper json,PlatformTransactionManager transactions){this.db=db;this.tenants=tenants;this.secrets=secrets;this.policy=policy;this.assertions=assertions;this.gateway=gateway;this.json=json;tx=new TransactionTemplate(transactions);Arrays.setAll(locks,i->new Object());db.update("UPDATE app.database_event SET status='INTERRUPTED',ended_at=CURRENT_TIMESTAMP WHERE status='RUNNING'");}
 private Object lock(UUID org,UUID id){return locks[Math.floorMod(Objects.hash(org,id),locks.length)];}
 private List<String> roles(UUID actor,UUID org){return tenants.requireMembership(actor,org).roles();}
 private void admin(UUID actor,UUID org){if(!roles(actor,org).contains("INTEGRATION_ADMIN"))throw new AccessDeniedException("Integration administrator required");}
 public long count(UUID actor,UUID org){roles(actor,org);return db.queryForObject("SELECT count(*) FROM app.database_connector WHERE organization_id=? AND NOT removed",Long.class,org);}
 private Revision revision(UUID org,UUID id){var rows=db.query("SELECT c.*,i.state,i.health FROM app.database_connector i JOIN app.database_configuration c ON c.organization_id=i.organization_id AND c.connector_id=i.id AND c.version=i.configuration_version WHERE i.organization_id=? AND i.id=? AND NOT i.removed",(r,n)->new Revision(org,id,r.getLong("version"),r.getString("database_type"),r.getString("host"),r.getInt("port"),r.getString("database_name"),json.readValue(r.getString("schemas"),List.class),r.getBoolean("tls"),r.getObject("credential_id",UUID.class),r.getString("fingerprint"),r.getString("state"),r.getString("health")),org,id);if(rows.size()!=1)throw new AccessDeniedException("Connector unavailable");return rows.getFirst();}
 private void validate(Registration r){if(r==null||r.displayName()==null||r.displayName().isBlank()||r.displayName().length()>100||r.displayName().chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException();policy.check(r.databaseType(),r.host(),r.port(),r.databaseName(),r.schemas(),r.tls());}
 public Map<String,Object> list(UUID actor,UUID org){var roles=roles(actor,org);return Map.of("available",true,"canManage",roles.contains("INTEGRATION_ADMIN"),"items",db.queryForList("SELECT i.id,i.display_name,i.state,i.health,i.configuration_version,i.last_validated_at,c.database_type,c.host,c.port,c.database_name,c.tls FROM app.database_connector i JOIN app.database_configuration c ON c.organization_id=i.organization_id AND c.connector_id=i.id AND c.version=i.configuration_version WHERE i.organization_id=? AND NOT removed ORDER BY i.created_at,i.id",org));}
 public Map<String,Object> detail(UUID actor,UUID org,UUID id){roles(actor,org);return view(org,id);}
 private Map<String,Object> view(UUID org,UUID id){var r=revision(org,id);var result=new LinkedHashMap<String,Object>(db.queryForMap("SELECT id,display_name,state,health,configuration_version,created_at,updated_at,last_validated_at FROM app.database_connector WHERE organization_id=? AND id=?",org,id));result.put("databaseType",r.type);result.put("host",r.host);result.put("port",r.port);result.put("databaseName",r.database);result.put("schemas",r.schemas);result.put("tls",r.tls);result.put("credentialConfigured",true);result.put("configurationFingerprint",r.fingerprint);
  result.put("revisions",db.queryForList("SELECT version,database_type,host,port,database_name,schemas,tls,fingerprint,created_by,created_at FROM app.database_configuration WHERE organization_id=? AND connector_id=? ORDER BY version DESC LIMIT 20",org,id));
  result.put("tables",db.query("SELECT * FROM app.database_table WHERE organization_id=? AND connector_id=? AND version=? ORDER BY present DESC,schema_name,table_name,discovered_at DESC LIMIT 128",(row,n)->{var t=new LinkedHashMap<String,Object>();UUID table=row.getObject("id",UUID.class);t.put("id",table);t.put("schema",row.getString("schema_name"));t.put("name",row.getString("table_name"));t.put("fingerprint",row.getString("fingerprint"));t.put("metadata",json.readValue(row.getString("metadata"),Map.class));t.put("present",row.getBoolean("present"));t.put("approvals",db.query("SELECT role,columns,status,actor,created_at FROM app.database_approval WHERE organization_id=? AND table_id=? ORDER BY created_at DESC LIMIT 30",(a,j)->Map.of("role",a.getString(1),"columns",json.readValue(a.getString(2),List.class),"status",a.getString(3),"actor",a.getObject(4),"createdAt",a.getTimestamp(5).toInstant().toString()),org,table));return t;},org,id,r.version));
  result.put("events",db.queryForList("SELECT id,actor,version,table_id,kind,status,error_code,started_at,ended_at,duration_ms FROM app.database_event WHERE organization_id=? AND connector_id=? ORDER BY started_at DESC,id LIMIT 30",org,id));return result;
 }
 public Map<String,Object> register(UUID actor,UUID org,Registration input){admin(actor,org);validate(input);UUID id=UUID.randomUUID();try{tx.executeWithoutResult(s->{db.execute("SELECT pg_advisory_xact_lock(33819004)");if(db.queryForObject("SELECT count(*) FROM app.database_connector WHERE NOT removed",Integer.class)>=64)throw new DatabaseFailure("DB_LIMIT");UUID credential=secrets.store(org,new DatabaseCredentials.Secret(input.username,input.password));db.update("INSERT INTO app.database_connector(organization_id,id,display_name,configuration_version,created_by) VALUES(?,?,?,1,?)",org,id,input.displayName.trim(),actor);insert(actor,org,id,1,credential,input);event(actor,org,id,1,null,"REGISTER","SUCCESS",null);});}catch(DuplicateKeyException e){throw new IllegalArgumentException();}return view(org,id);}
 private void insert(UUID actor,UUID org,UUID id,long version,UUID credential,Registration r){String fp=assertions.hash(List.of(r.databaseType,r.host,r.port,r.databaseName,r.schemas,r.tls,credential));db.update("INSERT INTO app.database_configuration(organization_id,connector_id,version,database_type,host,port,database_name,schemas,tls,credential_id,fingerprint,created_by) VALUES(?,?,?,?,?,?,?,?::jsonb,?,?,?,?)",org,id,version,r.databaseType,r.host,r.port,r.databaseName,json.writeValueAsString(r.schemas),r.tls,credential,fp,actor);}
 public Map<String,Object> edit(UUID actor,UUID org,UUID id,Registration input){admin(actor,org);validate(input);synchronized(lock(org,id)){var r=revision(org,id);try{tx.executeWithoutResult(s->{UUID secret=input.password==null||input.password.isEmpty()?r.credential:secrets.store(org,new DatabaseCredentials.Secret(input.username,input.password));if(db.update("UPDATE app.database_connector SET display_name=?,configuration_version=configuration_version+1,state='DRAFT',health='UNKNOWN',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND configuration_version=? AND NOT removed",input.displayName.trim(),org,id,r.version)!=1)throw new DatabaseFailure("DB_DISABLED");insert(actor,org,id,r.version+1,secret,input);stale(org,id,null);if(!secret.equals(r.credential))secrets.revoke(org,r.credential);event(actor,org,id,r.version+1,null,"EDIT","SUCCESS",null);});}catch(DuplicateKeyException e){throw new IllegalArgumentException();}gateway.retire(org,id);}gateway.reconcile();return view(org,id);}
 private void stale(UUID org,UUID id,UUID table){if(table==null)db.update("UPDATE app.database_approval SET status='STALE' WHERE organization_id=? AND status='APPROVED' AND table_id IN(SELECT id FROM app.database_table WHERE organization_id=? AND connector_id=?)",org,org,id);else db.update("UPDATE app.database_approval SET status='STALE' WHERE organization_id=? AND table_id=? AND status='APPROVED'",org,table);}
 public Map<String,Object> disable(UUID actor,UUID org,UUID id,boolean remove){admin(actor,org);synchronized(lock(org,id)){var r=revision(org,id);tx.executeWithoutResult(s->{db.update("UPDATE app.database_connector SET state='DISABLED',removed=?,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",remove,org,id);stale(org,id,null);if(remove)secrets.revoke(org,r.credential);event(actor,org,id,r.version,null,remove?"REMOVE":"DISABLE","SUCCESS",null);});gateway.retire(org,id);}gateway.reconcile();return remove?Map.of("removed",true):view(org,id);}
 public Map<String,Object> inspect(UUID actor,UUID org,UUID id){admin(actor,org);Revision r;synchronized(lock(org,id)){r=revision(org,id);if(r.state.equals("DISABLED"))throw new DatabaseFailure("DB_DISABLED");if(db.update("UPDATE app.database_connector SET state='VALIDATING' WHERE organization_id=? AND id=? AND configuration_version=? AND state<>'VALIDATING' AND state<>'DISABLED'",org,id,r.version)!=1)throw new DatabaseFailure("DB_BUSY");}
  try{var result=gateway.inspect(assertions.issue(actor,org,id,r.version,"INSPECT",UUID.randomUUID(),null,""));var tables=(List<Map<String,Object>>)result.get("tables");if(tables==null||tables.size()>64||json.writeValueAsBytes(result).length>262144)throw new DatabaseFailure("DB_LIMIT");synchronized(lock(org,id)){tx.executeWithoutResult(s->{if(db.update("UPDATE app.database_connector SET state='DRAFT',health='HEALTHY',last_validated_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND configuration_version=? AND state='VALIDATING' AND NOT removed",org,id,r.version)!=1)throw new DatabaseFailure("DB_DISABLED");db.update("UPDATE app.database_table SET present=false WHERE organization_id=? AND connector_id=? AND version=?",org,id,r.version);
    for(var table:tables){String schema=Objects.toString(table.get("schema"),""),name=Objects.toString(table.get("name"),"");if(!r.schemas.contains(schema)||name.isEmpty()||name.length()>128||json.writeValueAsBytes(table).length>32768||!(table.get("columns") instanceof List<?> cols)||cols.size()>64)throw new DatabaseFailure("DB_LIMIT");String fp=assertions.hash(table);db.update("INSERT INTO app.database_table(organization_id,connector_id,version,id,schema_name,table_name,fingerprint,metadata) VALUES(?,?,?,?,?,?,?,?::jsonb) ON CONFLICT(organization_id,connector_id,version,schema_name,table_name,fingerprint) DO UPDATE SET present=true,metadata=EXCLUDED.metadata,discovered_at=CURRENT_TIMESTAMP",org,id,r.version,UUID.randomUUID(),schema,name,fp,json.writeValueAsString(table));}
    db.update("UPDATE app.database_approval SET status='STALE' WHERE organization_id=? AND status='APPROVED' AND table_id IN(SELECT id FROM app.database_table WHERE organization_id=? AND connector_id=? AND NOT present)",org,org,id);event(actor,org,id,r.version,null,"INSPECT","SUCCESS",null);});}gateway.retire(org,id);gateway.reconcile();return view(org,id);
  }catch(Exception e){synchronized(lock(org,id)){db.update("UPDATE app.database_connector SET state='DRAFT',health='UNREACHABLE' WHERE organization_id=? AND id=? AND configuration_version=? AND state='VALIDATING'",org,id,r.version);event(actor,org,id,r.version,null,"INSPECT","FAILED",e instanceof DatabaseFailure d?d.code():"DB_UNAVAILABLE");}throw e instanceof DatabaseFailure d?d:new DatabaseFailure("DB_UNAVAILABLE");}
 }
 private Map<String,Object> table(Revision r,UUID id){var rows=db.query("SELECT metadata,fingerprint FROM app.database_table WHERE organization_id=? AND connector_id=? AND version=? AND id=? AND present",(row,n)->{var m=new LinkedHashMap<String,Object>(json.readValue(row.getString(1),Map.class));m.put("fingerprint",row.getString(2));return m;},r.org,r.id,r.version,id);if(rows.size()!=1)throw new AccessDeniedException("Table unavailable");return rows.getFirst();}
 public Map<String,Object> approve(UUID actor,UUID org,UUID id,UUID table,Scope scope){admin(actor,org);if(scope==null||!Set.of("INTEGRATION_ADMIN","USER").contains(scope.role))throw new IllegalArgumentException();synchronized(lock(org,id)){var r=revision(org,id);if(!r.health.equals("HEALTHY")||Set.of("DISABLED","VALIDATING").contains(r.state))throw new DatabaseFailure("DB_DISABLED");var meta=table(r,table);
   if(scope.approved){var names=((List<Map<String,Object>>)meta.get("columns")).stream().filter(c->Boolean.TRUE.equals(c.get("supported"))).map(c->(String)c.get("name")).toList();var pk=(List<String>)meta.get("primaryKey");if(scope.columns==null||scope.columns.isEmpty()||scope.columns.size()>20||new HashSet<>(scope.columns).size()!=scope.columns.size()||!names.containsAll(scope.columns)||pk==null||pk.isEmpty()||!scope.columns.containsAll(pk))throw new DatabaseFailure("DB_INVALID_QUERY");}
   if(scope.approved){var previous=db.query("SELECT columns FROM app.database_approval WHERE organization_id=? AND table_id=? AND role=? AND status='APPROVED'",(row,n)->json.readValue(row.getString(1),List.class),org,table,scope.role);if(!previous.isEmpty()&&!new HashSet<>(previous.getFirst()).equals(new HashSet<>(scope.columns))){tx.executeWithoutResult(s->{stale(org,id,table);db.update("UPDATE app.database_connector SET state='DRAFT',health='UNKNOWN' WHERE organization_id=? AND id=?",org,id);event(actor,org,id,r.version,table,"SCOPE_CHANGED","REVALIDATION_REQUIRED","DB_REVALIDATION_REQUIRED");});gateway.retire(org,id);gateway.reconcile();throw new DatabaseFailure("DB_REVALIDATION_REQUIRED");}}
   tx.executeWithoutResult(s->{db.update("UPDATE app.database_approval SET status='REVOKED' WHERE organization_id=? AND table_id=? AND role=? AND status='APPROVED'",org,table,scope.role);db.update("INSERT INTO app.database_approval(organization_id,id,table_id,role,columns,fingerprint,status,actor) VALUES(?,?,?,?,?::jsonb,?,?,?)",org,UUID.randomUUID(),table,scope.role,json.writeValueAsString(scope.approved?scope.columns:List.of()),meta.get("fingerprint"),scope.approved?"APPROVED":"REVOKED",actor);event(actor,org,id,r.version,table,scope.approved?"APPROVE":"REVOKE","SUCCESS",null);});gateway.retire(org,id);
  }gateway.reconcile();return view(org,id);
 }
 public Map<String,Object> activate(UUID actor,UUID org,UUID id){admin(actor,org);synchronized(lock(org,id)){var r=revision(org,id);if(!r.state.equals("DRAFT")||!r.health.equals("HEALTHY")||eligible(actor,r).isEmpty())throw new DatabaseFailure("DB_DISABLED");db.update("UPDATE app.database_connector SET state='ACTIVE',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",org,id);event(actor,org,id,r.version,null,"ACTIVATE","SUCCESS",null);}gateway.reconcile();return view(org,id);}
 private List<String> eligible(UUID actor,Revision r){var roles=roles(actor,r.org);if(!roles.contains("INTEGRATION_ADMIN")&&!roles.contains("USER"))return List.of();return db.queryForList("SELECT DISTINCT t.id::text FROM app.database_table t JOIN app.database_approval a ON a.organization_id=t.organization_id AND a.table_id=t.id AND a.fingerprint=t.fingerprint WHERE t.organization_id=? AND t.connector_id=? AND t.version=? AND t.present AND a.status='APPROVED' AND a.role=ANY(?::text[])",String.class,r.org,r.id,r.version,"{"+String.join(",",roles.stream().filter(x->Set.of("INTEGRATION_ADMIN","USER").contains(x)).toList())+"}");}
 public Map<String,Object> authorize(String assertion,String mode,UUID requestedTable){var c=assertions.verify(assertion);UUID actor=UUID.fromString((String)c.get("sub")),org=UUID.fromString((String)c.get("org")),id=UUID.fromString((String)c.get("connector"));var r=revision(org,id);roles(actor,org);if(((Number)c.get("revision")).longValue()!=r.version||r.state.equals("DISABLED"))throw new DatabaseFailure("DB_DISABLED");String action=(String)c.get("action");
  if(mode.equals("INSPECT")){if(!action.equals("INSPECT"))throw new DatabaseFailure("DB_ACCESS_DENIED");admin(actor,org);return material(r);}
  if(!r.state.equals("ACTIVE")||!r.health.equals("HEALTHY"))throw new DatabaseFailure("DB_DISABLED");var eligible=eligible(actor,r);
  if(mode.equals("LIST")){if(!Set.of("LIST","QUERY","DESCRIBE").contains(action))throw new DatabaseFailure("DB_ACCESS_DENIED");return Map.of("visible",!eligible.isEmpty());}
  if(!Set.of("QUERY","DESCRIBE").contains(action)||requestedTable==null||!requestedTable.toString().equals(c.get("table"))||!eligible.contains(requestedTable.toString()))throw new DatabaseFailure("DB_ACCESS_DENIED");
  UUID execution=UUID.fromString((String)c.get("execution"));if(db.queryForObject("SELECT count(*) FROM app.database_event WHERE organization_id=? AND connector_id=? AND id=? AND actor=? AND version=? AND table_id=? AND status='RUNNING'",Integer.class,org,id,execution,actor,r.version,requestedTable)!=1)throw new DatabaseFailure("DB_CANCELLED");
  var meta=table(r,requestedTable);var roleList=roles(actor,org);var columns=new TreeSet<String>();db.query("SELECT role,columns FROM app.database_approval WHERE organization_id=? AND table_id=? AND fingerprint=? AND status='APPROVED'",row->{if(roleList.contains(row.getString(1)))columns.addAll(json.readValue(row.getString(2),List.class));},org,requestedTable,meta.get("fingerprint"));var result=material(r);result.put("table",meta);result.put("columns",columns);return result;
 }
 private String grantEpoch(UUID org,UUID id,long version){return assertions.hash(db.queryForList("SELECT a.id::text FROM app.database_approval a JOIN app.database_table t ON t.organization_id=a.organization_id AND t.id=a.table_id AND t.fingerprint=a.fingerprint WHERE t.organization_id=? AND t.connector_id=? AND t.version=? AND t.present AND a.status='APPROVED' ORDER BY a.id",String.class,org,id,version));}
 private Map<String,Object> material(Revision r){policy.check(r.type,r.host,r.port,r.database,r.schemas,r.tls);var secret=secrets.resolve(r.org,r.credential);var m=new LinkedHashMap<String,Object>();m.put("organizationId",r.org);m.put("connectorId",r.id);m.put("revision",r.version);m.put("authorizationEpoch",grantEpoch(r.org,r.id,r.version));m.put("databaseType",r.type);m.put("host",r.host);m.put("port",r.port);m.put("databaseName",r.database);m.put("schemas",r.schemas);m.put("tls",r.tls);m.put("credentialReference",r.credential);m.put("username",secret.username());m.put("password",secret.password());return m;}
 public Map<String,Object> catalog(){var registrations=db.queryForList("SELECT organization_id,id,configuration_version FROM app.database_connector WHERE state<>'DISABLED' AND NOT removed LIMIT 64");for(var row:registrations)row.put("authorizationEpoch",grantEpoch((UUID)row.get("organization_id"),(UUID)row.get("id"),((Number)row.get("configuration_version")).longValue()));return Map.of("active",db.queryForObject("SELECT count(*)>0 FROM app.database_connector i WHERE state='ACTIVE' AND health='HEALTHY' AND NOT removed AND EXISTS(SELECT 1 FROM app.database_table t JOIN app.database_approval a ON a.organization_id=t.organization_id AND a.table_id=t.id AND a.fingerprint=t.fingerprint WHERE t.organization_id=i.organization_id AND t.connector_id=i.id AND t.version=i.configuration_version AND t.present AND a.status='APPROVED')",Boolean.class),"registrations",registrations);}
 public void drift(String assertion,UUID table){var c=assertions.verify(assertion);if(!table.toString().equals(c.get("table")))throw new DatabaseFailure("DB_ACCESS_DENIED");UUID org=UUID.fromString((String)c.get("org")),id=UUID.fromString((String)c.get("connector")),actor=UUID.fromString((String)c.get("sub"));synchronized(lock(org,id)){var r=revision(org,id);if(r.version!=((Number)c.get("revision")).longValue())return;table(r,table);tx.executeWithoutResult(s->{stale(org,id,table);db.update("UPDATE app.database_connector SET state='DRAFT',health='UNKNOWN' WHERE organization_id=? AND id=? AND state<>'DISABLED'",org,id);event(actor,org,id,r.version,table,"SCHEMA_CHANGED","DENIED","DB_SCHEMA_CHANGED");});}gateway.retire(org,id);}
 public Map<String,Object> tools(UUID actor,UUID org,UUID id){var r=revision(org,id);roles(actor,org);return Map.of("tools",gateway.tools(assertions.issue(actor,org,id,r.version,"LIST",UUID.randomUUID(),null,"")),"protocol","2025-11-25");}
 public Map<String,Object> query(UUID actor,UUID org,UUID id,UUID table,UUID execution,Map<String,Object> query,boolean describe){roles(actor,org);if(execution==null||query==null||json.writeValueAsBytes(query).length>16384)throw new DatabaseFailure("DB_INVALID_QUERY");var r=revision(org,id);var args=new LinkedHashMap<>(query);for(String k:args.keySet())if(!Set.of("columns","filters","order","limit","offset").contains(k))throw new DatabaseFailure("DB_INVALID_QUERY");args.put("connectorId",id.toString());args.put("revision",r.version);args.put("tableId",table.toString());String action=describe?"DESCRIBE":"QUERY";long started=System.nanoTime();try{db.update("INSERT INTO app.database_event(organization_id,connector_id,id,actor,version,table_id,kind,status) VALUES(?,?,?,?,?,?,?,'RUNNING')",org,id,execution,actor,r.version,table,action);}catch(DuplicateKeyException e){throw new DatabaseFailure("DB_INVALID_QUERY");}
  String assertion=assertions.issue(actor,org,id,r.version,action,execution,table,assertions.hash(args));try{var authorized=authorize(assertion,action,table);if(!describe)DatabaseArguments.check(query,(Map<String,Object>)authorized.get("table"),(Collection<String>)authorized.get("columns"));var result=gateway.call(assertion,describe?"database_describe_table":"database_read_rows",args);synchronized(lock(org,id)){authorize(assertion,action,table);if(db.update("UPDATE app.database_event SET status='SUCCESS',ended_at=CURRENT_TIMESTAMP,duration_ms=? WHERE organization_id=? AND id=? AND status='RUNNING'",(System.nanoTime()-started)/1000000,org,execution)!=1)throw new DatabaseFailure("DB_CANCELLED");return Map.of("result",result,"untrusted",true,"correlationId",execution,"protocol","2025-11-25","revision",r.version,"durationMs",(System.nanoTime()-started)/1000000);}
  }catch(Exception e){String code=e instanceof DatabaseFailure d?d.code():e instanceof AccessDeniedException?"DB_ACCESS_DENIED":"DB_UNAVAILABLE";if("CANCELLED".equals(db.queryForObject("SELECT status FROM app.database_event WHERE organization_id=? AND id=?",String.class,org,execution)))code="DB_CANCELLED";db.update("UPDATE app.database_event SET status='FAILED',error_code=?,ended_at=CURRENT_TIMESTAMP,duration_ms=? WHERE organization_id=? AND id=? AND status='RUNNING'",code,(System.nanoTime()-started)/1000000,org,execution);if(Set.of("DB_UNAVAILABLE","DB_TLS_FAILED","DB_AUTHENTICATION_FAILED").contains(code)){db.update("UPDATE app.database_connector SET health='UNREACHABLE' WHERE organization_id=? AND id=? AND configuration_version=? AND state='ACTIVE' AND NOT removed",org,id,r.version);gateway.retire(org,id);}throw e instanceof AccessDeniedException a?a:new DatabaseFailure(code);}
 }
 public Map<String,Object> cancel(UUID actor,UUID org,UUID id,UUID execution){var roles=roles(actor,org);revision(org,id);if(db.update("UPDATE app.database_event SET status='CANCELLED',error_code='DB_CANCELLED',ended_at=CURRENT_TIMESTAMP WHERE organization_id=? AND connector_id=? AND id=? AND status='RUNNING' AND (actor=? OR ?)",org,id,execution,actor,roles.contains("INTEGRATION_ADMIN"))==1)gateway.cancel(execution);return Map.of("cancelled",true);}
 private void event(UUID actor,UUID org,UUID id,long version,UUID table,String kind,String status,String error){db.update("INSERT INTO app.database_event(organization_id,connector_id,id,actor,version,table_id,kind,status,error_code,ended_at) VALUES(?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",org,id,UUID.randomUUID(),actor,version,table,kind,status,error);}
}
